definitions.css:
.d-raster-terminal-window{position:relative;width:100%;height:320px;box-sizing:border-box;overflow:hidden;background:#0a0a0b;color:#ececef;font-family:'JetBrains Mono',monospace;isolation:isolate}
.d-raster-terminal-window-stage{position:absolute;inset:0;overflow:hidden;touch-action:none;background:linear-gradient(rgba(35,35,39,.12) 1px,transparent 1px),linear-gradient(90deg,rgba(35,35,39,.1) 1px,transparent 1px),radial-gradient(circle at 50% 45%,#161619 0,#0a0a0b 72%);background-size:24px 24px,24px 24px,auto}
.d-raster-terminal-window-shell{position:absolute;left:0;top:0;width:min(440px,82%);height:244px;box-sizing:border-box;display:grid;grid-template-rows:32px 28px minmax(0,1fr);overflow:hidden;border:1px solid #232327;border-radius:4px;background:#101012;box-shadow:0 18px 50px rgba(0,0,0,.48);transform:translate3d(0,0,0);will-change:transform}
.d-raster-terminal-window-titlebar{display:grid;grid-template-columns:64px 1fr 64px;align-items:center;padding:0 10px;border-bottom:1px solid #232327;background:#161619;cursor:grab;user-select:none;touch-action:none;outline:none}.d-raster-terminal-window-titlebar:active{cursor:grabbing}.d-raster-terminal-window-titlebar:focus-visible{box-shadow:inset 0 0 0 1px #fa7319}
